do $$ begin if exists (select 1 from public.external_data_sources where source_key='osm') then update public.external_data_sources set active=true, name='OpenStreetMap', attribution_text='OpenStreetMap contributors', updated_at=now() where source_key='osm'; else insert into public.external_data_sources (source_key,name,attribution_text,active) values ('osm','OpenStreetMap','OpenStreetMap contributors',true); end if; end $$;
